-- Run after 01-init.sql in the wallet_demo database.
-- Create tables as the service role so authuser owns and can access them.
-- UUIDs are generated by Hibernate (GenerationType.UUID).
BEGIN;
SET LOCAL ROLE authuser;

CREATE TABLE auth.identity (
    id UUID PRIMARY KEY,
    username VARCHAR(255) NOT NULL UNIQUE
);

-- System and role are configuration-defined string identifiers.
-- Status uses JPA's default ORDINAL mapping:
-- status: Pending=0, Active=1, Locked=2, Closed=3
CREATE TABLE auth.profile (
    id UUID PRIMARY KEY,
    identity_id UUID NOT NULL,
    system VARCHAR(255) NOT NULL,
    role VARCHAR(255) NOT NULL,
    password VARCHAR(255) NOT NULL,
    status SMALLINT NOT NULL,
    token_version BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uk_profile_identity_system UNIQUE (identity_id, system),
    CONSTRAINT fk_profile_identity FOREIGN KEY (identity_id)
        REFERENCES auth.identity (id),
    CONSTRAINT ck_profile_system CHECK (length(trim(system)) > 0),
    CONSTRAINT ck_profile_role CHECK (length(trim(role)) > 0),
    CONSTRAINT ck_profile_status CHECK (status BETWEEN 0 AND 3)
);

-- OtpRecord is embedded directly in registration and activation.
-- OTP status: Send=0, Success=1, Fail=2
-- checked_at records the latest OTP verification attempt.
CREATE TABLE auth.registration (
    id UUID PRIMARY KEY,
    email VARCHAR(255) NOT NULL,
    registered_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    initialized_at TIMESTAMP(6) WITH TIME ZONE,
    otp_code VARCHAR(255) NOT NULL,
    status SMALLINT NOT NULL,
    send_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    expire_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    checked_at TIMESTAMP(6) WITH TIME ZONE,
    send_count INTEGER NOT NULL,
    fail_count INTEGER NOT NULL,
    CONSTRAINT ck_registration_otp_status CHECK (status BETWEEN 0 AND 2)
);

-- An activation may exist before its embedded OTP record is initialized.
CREATE TABLE auth.activation (
    id UUID PRIMARY KEY,
    email VARCHAR(255) NOT NULL,
    initialized_at TIMESTAMP(6) WITH TIME ZONE,
    otp_code VARCHAR(255),
    status SMALLINT,
    send_at TIMESTAMP(6) WITH TIME ZONE,
    expire_at TIMESTAMP(6) WITH TIME ZONE,
    checked_at TIMESTAMP(6) WITH TIME ZONE,
    send_count INTEGER DEFAULT 0,
    fail_count INTEGER DEFAULT 0,
    CONSTRAINT ck_activation_otp_status CHECK (status BETWEEN 0 AND 2)
);

-- Only a SHA-256 hash is stored; the raw login ticket is returned once.
CREATE TABLE auth.login_ticket (
    id UUID PRIMARY KEY,
    token_hash VARCHAR(64) NOT NULL UNIQUE,
    profile_id UUID NOT NULL REFERENCES auth.profile (id),
    client_id VARCHAR(255) NOT NULL,
    token_version BIGINT NOT NULL DEFAULT 0,
    expires_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    consumed_at TIMESTAMP(6) WITH TIME ZONE
);

-- Replicated PIN lock settings received from Management Service events.
CREATE TABLE auth.pin_lock_setting (
    system VARCHAR(255) PRIMARY KEY,
    temp_lock_fails_count INTEGER NOT NULL,
    temp_lock_wait_minutes INTEGER NOT NULL,
    permanent_lock_fails_count INTEGER NOT NULL,
    deleted BOOLEAN NOT NULL,
    version BIGINT NOT NULL
);

-- Per-profile PIN lock state is separate from the general profile status.
CREATE TABLE auth.pin_lock_state (
    profile_id UUID PRIMARY KEY REFERENCES auth.profile (id),
    status VARCHAR(32) NOT NULL,
    failed_attempt_count INTEGER NOT NULL,
    failed_since_temporary_lock INTEGER NOT NULL,
    locked_until TIMESTAMP(6) WITH TIME ZONE,
    last_failed_at TIMESTAMP(6) WITH TIME ZONE,
    status_changed_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    setting_version BIGINT NOT NULL,
    version BIGINT NOT NULL,
    CONSTRAINT ck_pin_lock_state_status CHECK (status IN ('Active', 'TemporarilyLocked', 'PermanentlyLocked')),
    CONSTRAINT ck_pin_lock_state_failed_attempt_count CHECK (failed_attempt_count >= 0),
    CONSTRAINT ck_pin_lock_state_failed_since_temp CHECK (failed_since_temporary_lock >= 0),
    CONSTRAINT ck_pin_lock_state_locked_until CHECK (
        (status = 'TemporarilyLocked' AND locked_until IS NOT NULL)
        OR (status <> 'TemporarilyLocked' AND locked_until IS NULL)
    )
);

CREATE TABLE auth.pin_lock_history (
    id UUID PRIMARY KEY,
    profile_id UUID NOT NULL REFERENCES auth.profile (id),
    action VARCHAR(32) NOT NULL,
    failed_attempt_count INTEGER NOT NULL,
    locked_until TIMESTAMP(6) WITH TIME ZONE,
    setting_version BIGINT NOT NULL,
    requested_by VARCHAR(255),
    occurred_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT ck_pin_lock_history_action CHECK (action IN ('TemporarilyLocked', 'PermanentlyLocked', 'TemporaryLockExpired', 'PermanentUnlocked')),
    CONSTRAINT ck_pin_lock_history_failed_attempt_count CHECK (failed_attempt_count >= 0)
);

CREATE INDEX ix_pin_lock_history_profile_occurred_at
    ON auth.pin_lock_history (profile_id, occurred_at);

CREATE TABLE auth.outbox_event (
    id UUID PRIMARY KEY,
    topic VARCHAR(100) NOT NULL,
    aggregate_key VARCHAR(255) NOT NULL,
    payload TEXT NOT NULL,
    created_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    published_at TIMESTAMP(6) WITH TIME ZONE,
    attempt_count INTEGER NOT NULL,
    last_error TEXT
);

CREATE INDEX ix_auth_outbox_event_pending
    ON auth.outbox_event (published_at, created_at);

-- Spring Security JDBC repositories (PostgreSQL-compatible types).
CREATE TABLE auth.oauth2_registered_client (
    id varchar(100) NOT NULL,
    client_id varchar(100) NOT NULL,
    client_id_issued_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    client_secret varchar(200) DEFAULT NULL,
    client_secret_expires_at timestamp with time zone DEFAULT NULL,
    client_name varchar(200) NOT NULL,
    client_authentication_methods varchar(1000) NOT NULL,
    authorization_grant_types varchar(1000) NOT NULL,
    redirect_uris varchar(1000) DEFAULT NULL,
    post_logout_redirect_uris varchar(1000) DEFAULT NULL,
    scopes varchar(1000) NOT NULL,
    client_settings varchar(2000) NOT NULL,
    token_settings varchar(2000) NOT NULL,
    PRIMARY KEY (id)
);

CREATE TABLE auth.oauth2_authorization (
    id varchar(100) NOT NULL,
    registered_client_id varchar(100) NOT NULL,
    principal_name varchar(200) NOT NULL,
    authorization_grant_type varchar(100) NOT NULL,
    authorized_scopes varchar(1000) DEFAULT NULL,
    attributes text DEFAULT NULL,
    state varchar(500) DEFAULT NULL,
    authorization_code_value text DEFAULT NULL,
    authorization_code_issued_at timestamp with time zone DEFAULT NULL,
    authorization_code_expires_at timestamp with time zone DEFAULT NULL,
    authorization_code_metadata text DEFAULT NULL,
    access_token_value text DEFAULT NULL,
    access_token_issued_at timestamp with time zone DEFAULT NULL,
    access_token_expires_at timestamp with time zone DEFAULT NULL,
    access_token_metadata text DEFAULT NULL,
    access_token_type varchar(100) DEFAULT NULL,
    access_token_scopes varchar(1000) DEFAULT NULL,
    oidc_id_token_value text DEFAULT NULL,
    oidc_id_token_issued_at timestamp with time zone DEFAULT NULL,
    oidc_id_token_expires_at timestamp with time zone DEFAULT NULL,
    oidc_id_token_metadata text DEFAULT NULL,
    refresh_token_value text DEFAULT NULL,
    refresh_token_issued_at timestamp with time zone DEFAULT NULL,
    refresh_token_expires_at timestamp with time zone DEFAULT NULL,
    refresh_token_metadata text DEFAULT NULL,
    user_code_value text DEFAULT NULL,
    user_code_issued_at timestamp with time zone DEFAULT NULL,
    user_code_expires_at timestamp with time zone DEFAULT NULL,
    user_code_metadata text DEFAULT NULL,
    device_code_value text DEFAULT NULL,
    device_code_issued_at timestamp with time zone DEFAULT NULL,
    device_code_expires_at timestamp with time zone DEFAULT NULL,
    device_code_metadata text DEFAULT NULL,
    PRIMARY KEY (id)
);

CREATE UNIQUE INDEX uk_oauth2_registered_client_client_id
    ON auth.oauth2_registered_client (client_id);
ALTER TABLE auth.oauth2_authorization
    ADD CONSTRAINT fk_oauth2_authorization_client FOREIGN KEY (registered_client_id)
    REFERENCES auth.oauth2_registered_client (id);

COMMIT;
